def gen(rng):
    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(v)
    def rname(lo, hi):
        return ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(rng.randint(lo, hi)))
    tests = [fmt(['neil']), fmt(['b', 'a']), fmt(['a', 'a', 'a']), fmt(['zed', 'amy', 'zed', 'amy', 'bob']),
             fmt(['raj', 'mia', 'raj', 'mia', 'lee', 'raj']), fmt(['ab', 'a', 'ab', 'a'])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            pool = [rname(1, 3) for _ in range(rng.randint(1, 5))]
            tests.append(fmt([rng.choice(pool) for _ in range(n)]))
    N = 100000
    pool = [rname(10, 10) for _ in range(50)]
    tests.append(fmt([rng.choice(pool) for _ in range(N)]))
    tests.append(fmt([rname(8, 10) for _ in range(N)]))
    tests.append(fmt([rng.choice(['zzzzzzzzzz', 'a']) for _ in range(N)]))
    pool2 = [rname(1, 10) for _ in range(3000)]
    tests.append(fmt([rng.choice(pool2) for _ in range(N)]))
    return tests

